PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS rooms(id TEXT PRIMARY KEY,name TEXT NOT NULL,area INTEGER NOT NULL,capacity INTEGER NOT NULL,base_rate INTEGER NOT NULL CHECK(base_rate>0),bed TEXT NOT NULL,photos TEXT NOT NULL,description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inventory(room_id TEXT REFERENCES rooms(id),date TEXT,capacity INTEGER NOT NULL CHECK(capacity>=0),used INTEGER NOT NULL DEFAULT 0 CHECK(used>=0 AND used<=capacity),rate INTEGER NOT NULL CHECK(rate>0),stop_sell INTEGER NOT NULL DEFAULT 0 CHECK(stop_sell IN(0,1)),min_stay INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(room_id,date));
CREATE TABLE IF NOT EXISTS quotes(id TEXT PRIMARY KEY,payload TEXT NOT NULL,total INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS holds(id TEXT PRIMARY KEY,quote_id TEXT NOT NULL UNIQUE REFERENCES quotes(id),status TEXT NOT NULL CHECK(status IN('active','converted','expired','released')),expires INTEGER NOT NULL,request_key TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS allocations(hold_id TEXT REFERENCES holds(id),room_id TEXT REFERENCES rooms(id),date TEXT,quantity INTEGER NOT NULL CHECK(quantity>0),PRIMARY KEY(hold_id,room_id,date));
CREATE TABLE IF NOT EXISTS reservations(id TEXT PRIMARY KEY,code TEXT UNIQUE NOT NULL,hold_id TEXT UNIQUE NOT NULL REFERENCES holds(id),status TEXT NOT NULL CHECK(status IN('awaiting_payment','confirmed','expired','cancelled','payment_review')),total INTEGER NOT NULL CHECK(total>0),guest TEXT NOT NULL,snapshot TEXT NOT NULL,access_hash TEXT NOT NULL UNIQUE,access_expires INTEGER NOT NULL,created INTEGER NOT NULL,request_key TEXT UNIQUE NOT NULL,fingerprint TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS payments(id TEXT PRIMARY KEY,reservation_id TEXT NOT NULL REFERENCES reservations(id),amount INTEGER NOT NULL CHECK(amount>0),status TEXT NOT NULL CHECK(status IN('pending','failed','paid')),created INTEGER NOT NULL,UNIQUE(reservation_id,amount));
CREATE TABLE IF NOT EXISTS payment_inbox(event_id TEXT PRIMARY KEY,payment_id TEXT REFERENCES payments(id),fingerprint TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ledger(id TEXT PRIMARY KEY,reservation_id TEXT REFERENCES reservations(id),payment_id TEXT REFERENCES payments(id),kind TEXT NOT NULL CHECK(kind IN('payment','refund')),amount INTEGER NOT NULL CHECK(amount>0),created INTEGER NOT NULL,UNIQUE(payment_id,kind));
CREATE TABLE IF NOT EXISTS requests(id TEXT PRIMARY KEY,reservation_id TEXT REFERENCES reservations(id),kind TEXT NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,reservation_id TEXT REFERENCES reservations(id),department TEXT NOT NULL,description TEXT NOT NULL,due_date TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY,aggregate_id TEXT NOT NULL,kind TEXT NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_run INTEGER NOT NULL,UNIQUE(aggregate_id,kind));
CREATE TABLE IF NOT EXISTS captures(id TEXT PRIMARY KEY REFERENCES outbox(id),payload TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS inquiries(id TEXT PRIMARY KEY,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'new',created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS admins(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('Admin','Manager','FO','Sales','Finance')));
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY,admin_id TEXT REFERENCES admins(id),expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,detail TEXT NOT NULL,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS hold_expiry ON holds(status,expires);
CREATE INDEX IF NOT EXISTS outbox_due ON outbox(status,next_run);
CREATE INDEX IF NOT EXISTS reservation_status ON reservations(status,created);
CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY);
INSERT OR IGNORE INTO schema_version VALUES(1);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES outbox(id),reservation_id TEXT NOT NULL REFERENCES reservations(id),audience TEXT NOT NULL CHECK(audience IN('guest','hotel')),recipient TEXT NOT NULL,subject TEXT NOT NULL,html TEXT NOT NULL,text TEXT NOT NULL,voucher_html TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('preview','sending','accepted','failed','review')),attempts INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL,started_at INTEGER,accepted_at INTEGER,provider_id TEXT,last_error TEXT,auto_dispatch INTEGER NOT NULL DEFAULT 0,document_json TEXT NOT NULL DEFAULT '{}',UNIQUE(event_id,audience));
CREATE INDEX IF NOT EXISTS notification_reservation ON notifications(reservation_id,created);
CREATE TABLE IF NOT EXISTS booking_settings(id INTEGER PRIMARY KEY CHECK(id=1),payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS booking_promos(code TEXT PRIMARY KEY,title TEXT NOT NULL,percent INTEGER NOT NULL CHECK(percent BETWEEN 0 AND 100),valid_from TEXT NOT NULL,valid_to TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS reservation_operations(reservation_id TEXT PRIMARY KEY REFERENCES reservations(id),room_number TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',distribution_fee INTEGER NOT NULL DEFAULT 0,settled INTEGER NOT NULL DEFAULT 0,settlement_date TEXT NOT NULL DEFAULT '',updated_by TEXT NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS payment_methods(reservation_id TEXT PRIMARY KEY REFERENCES reservations(id),method TEXT NOT NULL);
